INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (1, '拿破仑·波拿巴', 'Napoleon Bonaparte', '1769—1821', '18—19世纪', '法国', '皇帝 · 军事家', ARRAY['帝王', '军事', '法国'], '科西嘉出身的法国军事领袖与皇帝。他颁布的《拿破仑法典》奠定了现代大陆法系的基础，其远征与战略至今仍是军事研究的对象。', '狱友', '', 'assets/figures/napoleon.jpg', ARRAY['08-15', '12-02'], ARRAY['诞辰 · 1769年8月15日', '加冕 · 1804年12月2日'], ARRAY['birth', 'throne'], '他在圣赫勒拿岛上过了六年，身边只有一个愿意听他说话的人——那个人是你。', ARRAY['狱友', '同乡兵'], ARRAY['他在圣赫勒拿岛上过了六年，身边只有一个愿意听他说话的人——那个人是你。', '你和他同为科西嘉乡下人，进城后彼此是对方唯一敢说方言的对象。']),
  (2, '盖乌斯·尤利乌斯·凯撒', 'Gaius Julius Caesar', '前100—前44', '古罗马', '罗马', '独裁官 · 将军', ARRAY['帝王', '罗马', '军事'], '罗马共和国末期的独裁官与统帅。他征服高卢、渡过卢比孔河，终结了共和制度；其历法改革延用了上千年。', '债主', '', 'assets/figures/caesar.jpg', ARRAY['07-12', '01-10'], ARRAY['诞辰（传统说法） · 前100年7月12日', '渡卢比孔河 · 前49年1月10日'], ARRAY['birth', 'event'], '他欠你的账越滚越大，从未还清；最后那笔利息，是整个共和国的价钱。', ARRAY['债主', '渡口船夫'], ARRAY['他欠你的账越滚越大，从未还清；最后那笔利息，是整个共和国的价钱。', '他渡过卢比孔河那晚，船是你家那条，你蹲在岸边替他数人数。']),
  (3, '亚历山大大帝', 'Alexander the Great', '前356—前323', '古希腊', '马其顿', '国王 · 统帅', ARRAY['帝王', '军事', '希腊'], '马其顿国王，世界古代史上最年轻的征服者之一。他十年间横扫波斯、直抵印度河，把希腊文化传播到已知世界的尽头。', '随军史官', '', 'assets/figures/alexander.jpg', ARRAY['07-20', '10-01'], ARRAY['诞辰（传统说法） · 前356年7月20日', '高加米拉战役 · 前331年10月1日'], ARRAY['birth', 'event'], '史书写下了他所有的胜利，却从不写举笔的人是谁。', ARRAY['随军史官', '马厩伙计'], ARRAY['史书写下了他所有的胜利，却从不写举笔的人是谁。', '他的爱马布塞弗勒斯，喂料梳毛都是你，它只认你一个人。']),
  (4, '圣女贞德', 'Joan of Arc', '1412—1431', '中世纪', '法国', '军事领袖', ARRAY['军事', '法国', '宗教'], '法国民族英雄，农家少女出身。她自称受神启，在英法百年战争中率军解奥尔良之围，后被俘殉难，后世封圣。', '旗手', '', 'assets/figures/joan.jpg', ARRAY['01-06', '05-08'], ARRAY['诞辰（传统说法） · 1412年1月6日', '解奥尔良之围 · 1429年5月8日'], ARRAY['birth', 'event'], '她从不拔剑，于是那面白旗永远需要有人替她扛着。', ARRAY['旗手', '随营厨娘'], ARRAY['她从不拔剑，于是那面白旗永远需要有人替她扛着。', '出征路上她吃不惯军粮，是你偷偷给她留的那罐汤。']),
  (5, '伊丽莎白一世', 'Elizabeth I', '1533—1603', '16世纪', '英格兰', '女王', ARRAY['帝王', '英格兰', '黄金时代'], '英格兰与爱尔兰女王，都铎王朝最后的君主。她在宗教分裂中度过动荡童年，在位期间迎来英格兰的文艺复兴与海上崛起。', '姑祖母', '', 'assets/figures/elizabeth1.jpg', ARRAY['09-07', '01-14'], ARRAY['诞辰 · 1533年9月7日', '加冕 · 1559年1月14日'], ARRAY['birth', 'throne'], '她终身未嫁，把国家当成了孩子；你是家族里还常来串门的那一支。', ARRAY['姑祖母', '闺中密友'], ARRAY['她终身未嫁，把国家当成了孩子；你是家族里还常来串门的那一支。', '宫里人人争宠，唯独你敢在她面前说真话，于是成了她唯一的密友。']),
  (6, '路易十四', 'Louis XIV', '1638—1715', '17世纪', '法国', '国王', ARRAY['帝王', '法国', '专制'], '法国波旁王朝国王，史称太阳王。他亲政五十余载，营建凡尔赛宫、强化中央集权，将王权与宫廷文化推向极致。', '御前账房', '', 'assets/figures/louis14.jpg', ARRAY['09-05', '05-06'], ARRAY['诞辰 · 1638年9月5日', '凡尔赛宫启用 · 1682年5月6日'], ARRAY['birth', 'event'], '他一生最不缺黄金，最缺的是一个敢对他说实话的账房。', ARRAY['御前账房', '镜厅园丁'], ARRAY['他一生最不缺黄金，最缺的是一个敢对他说实话的账房。', '凡尔赛的镜厅是你亲手布置的，他每次路过都多看两眼。']),
  (7, '叶卡捷琳娜二世', 'Catherine the Great', '1729—1796', '18世纪', '俄国', '女皇', ARRAY['帝王', '俄国', '启蒙'], '俄国女皇，德意志小公国出身。她通过宫廷政变登位，在位期间扩张领土、推行启蒙改革，被称为俄国黄金时代的代表。', '合作者', '', 'assets/figures/catherine2.jpg', ARRAY['05-02', '06-18'], ARRAY['诞辰 · 1729年5月2日', '政变即位 · 1762年6月18日'], ARRAY['birth', 'throne'], '她靠一场政变登上王位，此后的每一步都有人替她商量。', ARRAY['合作者', '冬宫管家'], ARRAY['她靠一场政变登上王位，此后的每一步都有人替她商量。', '冬宫上下几百间房，钥匙串在你腰上，她笑称你是她的另一只手。']),
  (8, '维多利亚女王', 'Queen Victoria', '1819—1901', '19世纪', '英国', '女王', ARRAY['帝王', '英国', '殖民'], '英国汉诺威王朝女王，在位六十余年，见证了工业革命与日不落帝国的巅峰，其时代以她的名字命名。', '岳母', '', 'assets/figures/victoria.jpg', ARRAY['05-24', '06-20'], ARRAY['诞辰 · 1819年5月24日', '即位 · 1837年6月20日'], ARRAY['birth', 'throne'], '她撮合了整个欧洲的联姻，也因此成了半个欧洲的丈母娘。', ARRAY['岳母', '寡居笔友'], ARRAY['她撮合了整个欧洲的联姻，也因此成了半个欧洲的丈母娘。', '丈夫离世后，每晚给你写的信成了她唯一肯卸下威仪的时刻。']),
  (9, '乔治·华盛顿', 'George Washington', '1732—1799', '18世纪', '美国', '总统 · 将军', ARRAY['政治家', '美国', '军事'], '美国首任总统，独立战争大陆军总司令。他领导北美十三州赢得独立，两任之后主动归隐，确立了和平交权的先例。', '邻居', '', 'assets/figures/washington.jpg', ARRAY['02-22', '04-30'], ARRAY['诞辰 · 1732年2月22日', '就职 · 1789年4月30日'], ARRAY['birth', 'event'], '他功成身退回到乡间，两扇门之间的往来从来没断过。', ARRAY['邻居', '制桶匠'], ARRAY['他功成身退回到乡间，两扇门之间的往来从来没断过。', '他回乡后开了家蒸馏厂，第一只橡木桶是你替他箍的。']),
  (10, '亚伯拉罕·林肯', 'Abraham Lincoln', '1809—1865', '19世纪', '美国', '总统', ARRAY['政治家', '美国', '废奴'], '美国第16任总统，出身边疆。他在内战中维护联邦、废除奴隶制，并以《葛底斯堡演说》重塑了美国的立国理念。', '辩护律师', '', 'assets/figures/lincoln.jpg', ARRAY['02-12', '01-01'], ARRAY['诞辰 · 1809年2月12日', '《解放宣言》生效 · 1863年1月1日'], ARRAY['birth', 'event'], '你为一个将被处死的人做过辩护，他听完之后沉默了很久。', ARRAY['辩护律师', '劈柴工友'], ARRAY['你为一个将被处死的人做过辩护，他听完之后沉默了很久。', '他年轻时在伊利诺伊劈栅栏卖钱，木堆里总有你递过来的那根。'])
